`timescale 1ns/1ps
// Main oracle table generated by Python binascii.crc_hqx; no author recurrence.
module main_tb_crc16_byte;
reg [15:0] crc_in=0;
reg [7:0] data_in=0;
wire [15:0] crc_out;
deepeye_crc16_byte dut(.*);
reg [15:0] table0[0:65535];
integer seed,b,checks=0,i;
reg [15:0] want,state;
reg [7:0] digit;
initial begin
 $readmemh("oracle.hex",table0);
 $display("MAIN_BEGIN pairs=16777216");
 for(seed=0;seed<65536;seed=seed+1)begin
  for(b=0;b<256;b=b+1)begin
   crc_in=seed;data_in=b;want=table0[seed^(b<<8)];#1;checks++;
   if(crc_out!==want)begin
    $display("MAIN_MISMATCH seed=%0d byte=%0d got=%0d expected=%0d",seed,b,crc_out,want);
    $fatal(1,"main numeric mismatch");
   end
  end
 end
 state=16'hffff;
 for(i=1;i<=9;i=i+1)begin
  digit=8'h30+i;crc_in=state;data_in=digit;want=table0[state^(digit<<8)];#1;
  if(crc_out!==want)$fatal(1,"prefix mismatch");state=want;
 end
 if(state!==16'h29b1)$fatal(1,"standard check mismatch");
 $display("MAIN_STATS pairs=%0d prefix=9 standard=%0d",checks,state);
 $display("MAIN_PASS");$finish;
end
endmodule
